//! Byte-exact index reproduction against the committed corpus, PROTOCOL §13.
//!
//! This is the assertion the whole determinism property rests on. The vault in
//! `conformance/vaults/minimal/` carries index output generated by the
//! reference implementation; this test rebuilds every index from content alone
//! and compares the bytes, excluding only the two fields §13.2 names.
//!
//! If this test fails, one of the two implementations is wrong about the
//! protocol — which is exactly what it is for.

mod support;

use basalt::canonical::{parse_json, Json};
use basalt::transport::{FsTransport, MemoryTransport, Transport};
use basalt::vault::{Vault, INDEX_KEYS};
use support::conformance_dir;

/// The corpus pins `generated` to the epoch, so a run is comparable even
/// before §13.2's exclusion is applied.
const FIXED_GENERATED: &str = "1970-01-01T00:00:00Z";

fn minimal_vault() -> Vault {
    let dir = conformance_dir().join("vaults/minimal/vault");
    Vault::open(Box::new(FsTransport::new(&dir))).expect("minimal vault opens")
}

fn rebuild(vault: &mut Vault) {
    let scanned = vault.scan().expect("scan");
    vault
        .reindex_with(&scanned, FIXED_GENERATED, false)
        .expect("reindex");
}

#[test]
fn minimal_vault_indexes_match_byte_for_byte() {
    let mut vault = minimal_vault();
    rebuild(&mut vault);
    let indexes = vault.indexes.as_ref().unwrap();
    let expected_dir = conformance_dir().join("vaults/minimal/expected");

    let mut failures: Vec<String> = Vec::new();
    for (name, _) in INDEX_KEYS {
        let path = expected_dir.join(format!("{name}.json"));
        let Ok(text) = std::fs::read_to_string(&path) else {
            continue; // the corpus need not pin every index
        };
        let want: Json = parse_json(&text).expect("expected output is canonical JSON");
        let got = indexes.by_name(name).expect("index built");

        // §13.2: `generated` and the per-entry `etag` are excluded, since both
        // legitimately differ between two implementations. Everything else
        // MUST match byte for byte.
        let want_bytes = want.comparable().to_canonical_string();
        let got_bytes = got.comparable().to_canonical_string();

        if want_bytes != got_bytes {
            failures.push(format!(
                "index/{name}.json differs:\n{}",
                first_difference(&want_bytes, &got_bytes)
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "\n{} index object(s) do not reproduce:\n\n{}\n",
        failures.len(),
        failures.join("\n\n")
    );
}

/// With `generated` pinned to the corpus value, the raw bytes should match too
/// — a stricter check than §13.2 requires, and a useful one: it catches a
/// canonical-serializer bug that `comparable()` would paper over by
/// re-serializing both sides through the same writer.
#[test]
fn minimal_vault_raw_bytes_match_except_etags() {
    let mut vault = minimal_vault();
    rebuild(&mut vault);
    let indexes = vault.indexes.as_ref().unwrap();
    let expected_dir = conformance_dir().join("vaults/minimal/expected");

    for (name, _) in INDEX_KEYS {
        let path = expected_dir.join(format!("{name}.json"));
        let Ok(want_text) = std::fs::read_to_string(&path) else {
            continue;
        };
        let got_text = indexes.by_name(name).unwrap().to_canonical_string();
        if name == "nodes" {
            // `nodes.json` is the one index carrying `etag`, which §13.2
            // excludes; every other index must match the stored bytes exactly.
            continue;
        }
        assert_eq!(
            want_text,
            got_text,
            "index/{name}.json raw bytes differ:\n{}",
            first_difference(&want_text, &got_text)
        );
    }
}

/// §0 and §10: every index is derived. Delete all of them and a conforming
/// implementation rebuilds the lot from content alone, byte for byte.
#[test]
fn indexes_rebuild_from_content_alone() {
    let dir = conformance_dir().join("vaults/minimal/vault");
    let store = MemoryTransport::new();

    // Copy content, meta and principals into a fresh store — and nothing from
    // index/, so there is no stored index to accidentally read.
    let src = FsTransport::new(&dir);
    for key in src.list_all("").expect("list") {
        if key.starts_with("index/") {
            continue;
        }
        store.seed(&key, src.get(&key).unwrap().unwrap());
    }

    let mut vault = Vault::open(Box::new(store)).expect("vault opens without indexes");
    let scanned = vault.scan().unwrap();
    vault.reindex_with(&scanned, FIXED_GENERATED, true).unwrap();

    // Now read the indexes back out of the store and confirm they match the
    // corpus — proving the round trip through `put` is byte-preserving too.
    let stored = vault.load_stored_indexes().unwrap();
    let expected_dir = conformance_dir().join("vaults/minimal/expected");
    for (name, _) in INDEX_KEYS {
        let Ok(text) = std::fs::read_to_string(expected_dir.join(format!("{name}.json"))) else {
            continue;
        };
        let want = parse_json(&text)
            .unwrap()
            .comparable()
            .to_canonical_string();
        let got = stored
            .get(name)
            .unwrap_or_else(|| panic!("index/{name}.json was written"))
            .comparable()
            .to_canonical_string();
        assert_eq!(want, got, "index/{name}.json after a write/read round trip");
    }
}

/// §10.3 requires `backlinks.json` to be regenerable from `links.json` alone,
/// and says the conformance suite checks that the stored file equals the
/// recomputation.
#[test]
fn backlinks_are_derivable_from_links() {
    let mut vault = minimal_vault();
    rebuild(&mut vault);
    let indexes = vault.indexes.as_ref().unwrap();

    let mut recomputed: std::collections::BTreeMap<String, Vec<String>> = Default::default();
    for e in indexes.links.get("entries").unwrap().as_array().unwrap() {
        let Some(to) = e.get("to").and_then(|t| t.as_str()) else {
            continue;
        };
        let from = e.get("from").unwrap().as_str().unwrap().to_string();
        let v = recomputed.entry(to.to_string()).or_default();
        if !v.contains(&from) {
            v.push(from);
        }
    }
    for v in recomputed.values_mut() {
        v.sort();
    }

    let stored = indexes
        .backlinks
        .get("entries")
        .unwrap()
        .as_object()
        .unwrap();
    let as_map: std::collections::BTreeMap<String, Vec<String>> = stored
        .iter()
        .map(|(k, v)| {
            (
                k.clone(),
                v.as_array()
                    .unwrap()
                    .iter()
                    .map(|x| x.as_str().unwrap().to_string())
                    .collect(),
            )
        })
        .collect();

    assert_eq!(as_map, recomputed, "backlinks must equal the recomputation");
}

/// §10.6: the digest is over `content/` only, and the empty content tree has
/// root `sha256("")`.
#[test]
fn empty_content_tree_digest() {
    let d = basalt::indexer::compute_digest(&[]);
    assert_eq!(
        d.root,
        "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
    );
    assert_eq!(d.count, 0);
    assert!(d.tree.is_empty());
}

/// A readable report of where two canonical strings first diverge.
fn first_difference(want: &str, got: &str) -> String {
    let w: Vec<&str> = want.lines().collect();
    let g: Vec<&str> = got.lines().collect();
    for i in 0..w.len().max(g.len()) {
        let a = w.get(i).copied().unwrap_or("<missing>");
        let b = g.get(i).copied().unwrap_or("<missing>");
        if a != b {
            let from = i.saturating_sub(3);
            let mut out = String::new();
            for line in w.iter().take(i).skip(from) {
                out.push_str(&format!("      {line}\n"));
            }
            out.push_str(&format!("  want {a}\n   got {b}\n"));
            return out;
        }
    }
    "(identical line-by-line; a trailing-byte difference)".to_string()
}
